import enum, re
class Arity(enum.Enum):
    OPTIONAL=1; ZERO_OR_ONE=1; EXACTLY_ONE=2; EXACTLY_TWO=3; ZERO_OR_MORE=4; AT_LEAST_ONE=5; ONE_OR_MORE=5
SyntaxSpecification = list
class Node:
    def __init__(self, flag=None, alias=(), flag_followed_by_equals=False, choices=None, arity=Arity.OPTIONAL,
                 dash_as_stdin=False, min=None, max=None, suffixes=None, of=None, separator=","):
        self.flag=flag; self.alias=list(alias); self.eq=flag_followed_by_equals; self.choices=choices
        self.arity=arity; self.dash_as_stdin=dash_as_stdin; self.min=min; self.max=max
        self.suffixes=suffixes; self.of=of; self.separator=separator
    def names(self): return [self.flag]+self.alias
    def validate(self, v): return True
class Flag(Node):
    def __init__(self, flag, alias=()): super().__init__(flag=flag, alias=alias)
class Path(Node): pass
class String(Node): pass
class Selection(Node):
    def validate(self, v): return v in self.choices
_SIZE_SUF = r"(c|w|b|B|kB|K|KB|KiB|k|MB|M|MiB|xM|GB|G|GiB|TB|T|TiB|PB|P|PiB|EB|E|EiB|ZB|Z|ZiB|YB|Y|YiB|RB|R|RiB|QB|Q|QiB)?"
class Integer(Node):
    def validate(self, v):
        suf = "(" + "|".join(sorted(map(re.escape, self.suffixes or []), key=len, reverse=True)) + ")?" if self.suffixes else ""
        term = r"\+?[0-9]+" + suf
        if not re.fullmatch(f"{term}(x{term})*", v): return False
        n = int(re.match(r"\+?[0-9]+", v).group())
        return self.min is None or n >= self.min or "x" in v
class Size(Node):
    def validate(self, v):
        term = r"\+?[0-9]+" + _SIZE_SUF
        return bool(re.fullmatch(f"{term}(x{term})*", v)) and re.match(r"\+?([0-9]+)", v).group(1) != "0"*len(re.match(r"\+?([0-9]+)", v).group(1))
class List(Node):
    def validate(self, v):
        parts = v.split(self.separator)
        return all(p != "" and self.of.validate(p) for p in parts)
