def accepts(spec, argv):
    """Check argv against a syntax spec: returns True if it conforms."""
    for syntax in spec:
        options, positionals = syntax[0], syntax[1]
        ok = True
        for a in argv:
            matched = False
            for node in options:
                if isinstance(node, Flag):
                    if a in node.names(): matched = True; break
                elif node.eq and "=" in a:
                    k, v = a.split("=", 1)
                    if k in node.names():
                        matched = node.validate(v); break
            if not matched:
                ok = False; break
        if ok and not positionals: return True
    return False
